import{_ as n,c as t,o as a,ah as r}from"./chunks/framework.oAolcYhj.js";const i="/Qonnectra-docs/pr-14/images/manual/teil-a/map.jpg",s="/Qonnectra-docs/pr-14/images/manual/teil-a/map_selected_object.jpg",k=JSON.parse('{"title":"5. Karte","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/05-karte.md","filePath":"manual/teil-a-anwenderhandbuch/05-karte.md"}'),h={name:"manual/teil-a-anwenderhandbuch/05-karte.md"};function o(d,e,l,u,c,b){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="_5-karte" tabindex="-1">5. Karte <a class="header-anchor" href="#_5-karte" aria-label="Permalink to &quot;5. Karte&quot;">​</a></h1><p>Die Karte ist eines der zentralen Werkzeuge in Qonnectra. Sie dient der visuellen Darstellung des Netzbestands, der Orientierung im Raum und dem schnellen Aufruf von Informationen zu einzelnen Netzobjekten. Sie erreichen die Karte über die linke Navigation durch Klicken auf den Menüpunkt „Karte“.</p><p><img src="'+i+'" alt="Screenshot Karte" data-zoomable="true"></p><p>Bewegung, Legende, Transparenz und Suche funktionieren wie in Kapitel <a href="./03-wiederkehrende-bedienelemente.html">Wiederkehrende Bedienelemente</a> beschrieben. Dieses Kapitel behandelt, was nur für die Kartenansicht gilt.</p><h2 id="_5-1-kartenausschnitt-zoomstufe-und-gespeicherte-position" tabindex="-1">5.1 Kartenausschnitt, Zoomstufe und gespeicherte Position <a class="header-anchor" href="#_5-1-kartenausschnitt-zoomstufe-und-gespeicherte-position" aria-label="Permalink to &quot;5.1 Kartenausschnitt, Zoomstufe und gespeicherte Position&quot;">​</a></h2><p>Wenn Sie bei geöffneter Karte ein anderes Projekt auswählen, springt die Karte nicht automatisch in dessen Gebiet. Um dorthin zu gelangen, klicken Sie in der Legende oben rechts beim Eintrag „Adresse“ auf das Lupensymbol „Auf Ausdehnung zoomen“, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-3-das-kartenfenster">Das Kartenfenster</a>.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Qonnectra merkt sich den letzten Kartenausschnitt. Wenn Sie die Karte erneut öffnen, sehen Sie wieder die Stelle, an der Sie zuletzt gearbeitet haben.</p></div><h2 id="_5-2-layer-der-karte" tabindex="-1">5.2 Layer der Karte <a class="header-anchor" href="#_5-2-layer-der-karte" aria-label="Permalink to &quot;5.2 Layer der Karte&quot;">​</a></h2><p>Die Legende führt die Objektarten des Netzbestands als eigene Layer: „Adresse“, „Netzknoten“, „Trasse“, „Rohr“ und „Gebiet“, dazu die Hintergrundkarte „OpenStreetMap“. „Netzknoten“ und „Gebiet“ lassen sich nach Typen aufklappen, sodass Sie etwa nur die Hausanschlüsse oder nur die Projektgebiete einblenden.</p><p>Wie Sie die Layer schalten, beschreibt Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-3-das-kartenfenster">Das Kartenfenster</a>. Die Farben und Formen der Layer stellen Sie unter „Einstellungen“ ein, siehe Kapitel <a href="./17-einstellungen.html">Einstellungen</a>.</p><h2 id="_5-3-objekte-auswahlen-und-eigenschaften-lesen" tabindex="-1">5.3 Objekte auswählen und Eigenschaften lesen <a class="header-anchor" href="#_5-3-objekte-auswahlen-und-eigenschaften-lesen" aria-label="Permalink to &quot;5.3 Objekte auswählen und Eigenschaften lesen&quot;">​</a></h2><p>Wenn Sie ein Objekt (z. B. eine Trasse oder einen Netzknoten) auf der Karte anklicken, öffnet sich auf der rechten Seite die <strong>Info-Box</strong>, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-6-der-infobereich-mit-seinen-reitern">Der Infobereich</a>. Welche Reiter sie enthält, hängt von der Objektart ab:</p><ul><li>Trasse: „Eigenschaften“, „Rohrübersicht“, „Kabelübersicht“, „Aktionen“, „Anhänge“</li><li>Netzknoten und Adresse: „Eigenschaften“, „Aktionen“, „Anhänge“</li><li>Gebiet: „Eigenschaften“, „Anhänge“</li></ul><p>Die Angaben im Reiter „Eigenschaften“ sind hier nicht bearbeitbar, sondern dienen als Informationsquelle. Bearbeiten können Sie in der Karte ausschließlich den Reiter „Anhänge“, siehe Abschnitt <a href="#_5-8-anhange-an-einem-kartenobjekt">Anhänge an einem Kartenobjekt</a>.</p><p><img src="'+s+'" alt="Screenshot Karte mit Hervorhebung eines ausgewählten Objekts und der Anzeige der Details in einer Info-Box rechts" data-zoomable="true"></p><h2 id="_5-4-trasse-reiter-„rohrubersicht-und-„kabelubersicht" tabindex="-1">5.4 Trasse: Reiter „Rohrübersicht“ und „Kabelübersicht“ <a class="header-anchor" href="#_5-4-trasse-reiter-„rohrubersicht-und-„kabelubersicht" aria-label="Permalink to &quot;5.4 Trasse: Reiter „Rohrübersicht“ und „Kabelübersicht“&quot;">​</a></h2><p>Der Reiter „Rohrübersicht“ zeigt die Rohre der ausgewählten Trasse, siehe Kapitel <a href="./10-rohrverwaltung.html">Rohrverwaltung</a>, „Kabelübersicht“ die darin liegenden Kabel.</p><p><em>Die Dokumentation zu diesem Abschnitt ist noch in Arbeit.</em></p><h2 id="_5-5-grabenprofil-einer-trasse" tabindex="-1">5.5 Grabenprofil einer Trasse <a class="header-anchor" href="#_5-5-grabenprofil-einer-trasse" aria-label="Permalink to &quot;5.5 Grabenprofil einer Trasse&quot;">​</a></h2><p>Im Reiter „Aktionen“ einer Trasse öffnet „Grabenprofil anzeigen“ den Querschnitt des Grabens mit der Lage der Rohre.</p><p><em>Die Dokumentation zu diesem Abschnitt ist noch in Arbeit.</em></p><h2 id="_5-6-netzknoten-slot-konfiguration-und-struktur-offnen" tabindex="-1">5.6 Netzknoten: Slot-Konfiguration und Struktur öffnen <a class="header-anchor" href="#_5-6-netzknoten-slot-konfiguration-und-struktur-offnen" aria-label="Permalink to &quot;5.6 Netzknoten: Slot-Konfiguration und Struktur öffnen&quot;">​</a></h2><p>Im Reiter „Aktionen“ eines Netzknotens führen „Slot-Konfiguration anzeigen“ und „Struktur anzeigen“ zu dessen innerem Aufbau.</p><p><em>Die Dokumentation zu diesem Abschnitt ist noch in Arbeit.</em></p><h2 id="_5-7-von-der-karte-in-den-faserweg-wechseln" tabindex="-1">5.7 Von der Karte in den Faserweg wechseln <a class="header-anchor" href="#_5-7-von-der-karte-in-den-faserweg-wechseln" aria-label="Permalink to &quot;5.7 Von der Karte in den Faserweg wechseln&quot;">​</a></h2><p>Im Reiter „Aktionen“ eines Netzknotens oder einer Adresse springt „Folgen“ in die Ansicht „Faserweg“, siehe Kapitel <a href="./15-faserweg.html">Faserweg</a>.</p><p><em>Die Dokumentation zu diesem Abschnitt ist noch in Arbeit.</em></p><h2 id="_5-8-anhange-an-einem-kartenobjekt" tabindex="-1">5.8 Anhänge an einem Kartenobjekt <a class="header-anchor" href="#_5-8-anhange-an-einem-kartenobjekt" aria-label="Permalink to &quot;5.8 Anhänge an einem Kartenobjekt&quot;">​</a></h2><p>Zu jedem Kartenobjekt können Sie Dateien ablegen. Hochladen, Herunterladen, Umbenennen und Löschen funktionieren wie in Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-7-anhange-hochladen-ansehen-und-loschen">Anhänge hochladen, ansehen und löschen</a> beschrieben.</p><h2 id="_5-9-grenzen-der-darstellung" tabindex="-1">5.9 Grenzen der Darstellung <a class="header-anchor" href="#_5-9-grenzen-der-darstellung" aria-label="Permalink to &quot;5.9 Grenzen der Darstellung&quot;">​</a></h2><p>Ein Klick auf eine freie Stelle der Karte hebt die Auswahl auf – innerhalb eines Projektgebiets ist das allerdings kaum möglich, weil dessen Fläche die gesamte Umgebung überdeckt; schließen Sie die Info-Box dann über das Kreuz „Seitenleiste schließen“.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Trassen sind nur wenige Pixel breit und laufen an Netzknoten zusammen. Treffen Sie beim Klicken nicht das gewünschte Objekt, zoomen Sie weiter hinein oder blenden Sie den Layer „Gebiet“ vorübergehend aus.</p></div>',32)])])}const g=n(h,[["render",o]]);export{k as __pageData,g as default};
